def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next(c for c in range(w) if all(row[c] == 4 for row in grid))
    out = [[0] * divider for _ in range(h)]

    marker = next((r, c) for r, row in enumerate(grid)
                  for c, value in enumerate(row) if value == 5)
    x = marker[1] - divider - 1
    out[0][x] = 5
    y = 1

    templates = {
        ((1, 1, 0), (1, 0, 1), (0, 1, 0)): ("H", 1, 3),
        ((1, 0, 1), (1, 0, 1), (1, 1, 1)): ("H", -1, 2),
        ((1, 0, 1), (0, 1, 0), (0, 1, 0)): ("V", 0, 2),
        ((1, 1, 1), (0, 1, 0), (1, 0, 1)): ("H", -1, 4),
    }

    # Read the tile columns from left to right, top to bottom within each.
    for left in range(0, divider, 4):
        for top in range(0, h - 2, 4):
            cells = [[grid[top + dy][left + dx] for dx in range(3)]
                     for dy in range(3)]
            shape = tuple(tuple(int(v != 0) for v in row) for row in cells)
            if shape not in templates:
                continue
            color = next(v for row in cells for v in row if v not in (0, 4))
            direction, dx, length = templates[shape]

            if direction == "H":
                for k in range(length):
                    col = x + dx * k
                    if 0 <= y < h and 0 <= col < divider:
                        out[y][col] = color
                x += dx * (length - 1)
                y += 1
            else:
                for k in range(length):
                    if y + k < h and 0 <= x < divider:
                        out[y + k][x] = color
                y += length

    return out
